import { useLayoutEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { Route, useLocation } from 'react-router-dom';
import './email-password-auth/register';
import { LoginPage, RegisterPage, AccountPage, RequireAuth } from './email-password-auth/pages';
import { UserMenu } from './email-password-auth/components/UserMenu';

/**
 * Placement slot for platform chrome. Render this in your header where the
 * account / user menu belongs; installed recipes portal their chrome into it.
 * Renders nothing on its own, and is safe to render when no recipe is installed.
 */
export function RecipeSlot({ name }: { name: 'user-menu' }) {
  return <div data-recipe-slot={name} className="contents" />;
}

export const recipeRoutes = (
  <>
    <Route path="/login" element={<LoginPage />} />
    <Route path="/register" element={<RegisterPage />} />
    <Route path="/account" element={<RequireAuth><AccountPage /></RequireAuth>} />
  </>
);

/**
 * Paths the recipes themselves own. These pages render their own shell and no
 * header, so they can never carry the slot — the fallback below must not read
 * that as the app having forgotten to place one.
 */
const RECIPE_OWN_ROUTES: readonly string[] = ['/login', '/register', '/account'];

function RecipeChrome() {
  const { pathname } = useLocation();
  const [slot, setSlot] = useState<HTMLElement | null>(null);
  useLayoutEffect(() => {
    setSlot(document.querySelector<HTMLElement>('[data-recipe-slot="user-menu"]'));
  }, [pathname]);

  const chrome = (
    <>
      <UserMenu />
    </>
  );

  if (slot) return createPortal(chrome, slot);
  // A recipe page has no header by design; the corner is for a missing one.
  if (RECIPE_OWN_ROUTES.includes(pathname)) return null;
  return <div className="fixed right-3 top-3 z-50">{chrome}</div>;
}

export const recipeChrome = <RecipeChrome />;
